isCurrentScopeArrowHead(): boolean {
  const scope = this._currentExpressionScope;
  if (!scope) {
    this._expressionScopeDepth = this.expressionScope.stack.length;
    return false;
  }
  this._expressionScopeDepth = this.expressionScope.stack.length;
  if (typeof scope.canBeArrowParameterDeclaration === "function") {
